import React, { useState } from "react";
import { sendMessage } from "../api";

type Msg = { from: "user" | "bot"; text: string };

export function ChatWidget() {
  const [messages, setMessages] = useState<Msg[]>([
    { from: "bot", text: "Hi! How can I help you with your order or tariff today?" },
  ]);
  const [draft, setDraft] = useState("");

  async function submit() {
    const text = draft.trim();
    if (!text) return;
    setDraft("");
    setMessages((m) => [...m, { from: "user", text }]);
    const { reply } = await sendMessage(text);
    setMessages((m) => [...m, { from: "bot", text: reply }]);
  }

  return (
    <aside className="chat">
      <header>
        <strong>ACME Support</strong>
        <p className="disclosure">
          You are chatting with an AI assistant. It can make mistakes; ask for a human agent at any time.
          See our <a href="/privacy#support-chat">privacy notice</a>.
        </p>
      </header>
      <ol className="messages">
        {messages.map((m, i) => (
          <li key={i} className={m.from}>{m.text}</li>
        ))}
      </ol>
      <footer>
        <input value={draft} onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} />
        <button onClick={submit}>Send</button>
      </footer>
    </aside>
  );
}

import OpenAI from "openai";
import { searchHelpCentre } from "./retrieval";
import { history } from "./transcripts";

const client = new OpenAI();
const MODEL = process.env.LLM_MODEL ?? "gpt-4o-mini";

const SYSTEM_PROMPT = `You are the ACME Home Energy support assistant. Answer only questions about
orders, deliveries, invoices and tariffs using the provided help-centre extracts. If you are not sure,
or the customer asks for a person, reply with HANDOVER. Never give legal or financial advice.`;

export type Reply = { text: string; model: string; handover: boolean; usage: { prompt: number; completion: number } };

export async function answer(sessionId: string, message: string): Promise<Reply> {
  const context = await searchHelpCentre(message, 4);
  const past = await history(sessionId, 12);
  const completion = await client.chat.completions.create({
    model: MODEL,
    temperature: 0.2,
    messages: [
      { role: "system", content: SYSTEM_PROMPT },
      { role: "system", content: `Help-centre extracts:\n${context.join("\n---\n")}` },
      ...past,
      { role: "user", content: message },
    ],
  });
  const text = completion.choices[0]?.message?.content ?? "";
  // TODO(SUP-88): label AI-generated replies (AI Act Art. 50(2)) once the design team has a badge.
  return {
    text: text.replace("HANDOVER", "Let me connect you with a colleague."),
    model: completion.model,
    handover: text.includes("HANDOVER"),
    usage: { prompt: completion.usage?.prompt_tokens ?? 0, completion: completion.usage?.completion_tokens ?? 0 },
  };
}

import express from "express";
import rateLimit from "express-rate-limit";
import helmet from "helmet";
import { loadConfig } from "./config";
import { answer } from "./llm";
import { logLlmCall } from "./logging";
import { requireAdmin, sessionAuth } from "./auth";
import { appendMessage, deleteCustomerData, exportTranscript, startRetentionJob } from "./transcripts";

const cfg = loadConfig();
const app = express();
app.use(helmet());
app.use(express.json({ limit: "16kb" }));

// /api/chat is declared public in config/app.yaml (public_endpoints)
const chatLimiter = rateLimit({
  windowMs: 60_000,
  limit: cfg.rate_limit.chat_per_minute,
  keyGenerator: (req) => req.header("x-session-id") ?? req.ip ?? "anon",
});

app.post("/api/chat", chatLimiter, sessionAuth, async (req, res) => {
  const { sessionId, customerId } = res.locals;
  const text = String(req.body.message ?? "").slice(0, 2000);
  await appendMessage(sessionId, customerId, "user", text);
  const started = Date.now();
  const reply = await answer(sessionId, text);
  logLlmCall({ sessionId, model: reply.model, promptTokens: reply.usage.prompt, completionTokens: reply.usage.completion, latencyMs: Date.now() - started, handover: reply.handover });
  await appendMessage(sessionId, customerId, "assistant", reply.text);
  res.json({ reply: reply.text, handover: reply.handover });
});

app.get("/admin/transcripts/:customerId", requireAdmin, async (req, res) => {
  res.json(await exportTranscript(req.params.customerId));
});

app.delete("/admin/customers/:customerId/data", requireAdmin, async (req, res) => {
  // data subject erasure request (ticket from the privacy team)
  await deleteCustomerData(req.params.customerId);
  res.status(204).end();
});

startRetentionJob(cfg.retention.transcript_days);
app.listen(cfg.port, () => console.info(`supportbot listening on ${cfg.port}`));

import { Pool } from "pg";

const pool = new Pool({ connectionString: process.env.DATABASE_URL, ssl: { rejectUnauthorized: true } });

export async function appendMessage(sessionId: string, customerId: string | null, role: string, content: string) {
  // full message text is stored as typed by the customer (may include e-mail, phone, address)
  await pool.query(
    "INSERT INTO transcript_messages (session_id, customer_id, role, content, created_at) VALUES ($1,$2,$3,$4,now())",
    [sessionId, customerId, role, content],
  );
}

export async function history(sessionId: string, n: number) {
  const { rows } = await pool.query(
    "SELECT role, content FROM transcript_messages WHERE session_id=$1 ORDER BY created_at DESC LIMIT $2",
    [sessionId, n],
  );
  return rows.reverse();
}

export async function exportTranscript(customerId: string) {
  const { rows } = await pool.query("SELECT * FROM transcript_messages WHERE customer_id=$1 ORDER BY created_at", [customerId]);
  return rows;
}

export async function deleteCustomerData(customerId: string) {
  await pool.query("DELETE FROM transcript_messages WHERE customer_id=$1", [customerId]);
  await pool.query("DELETE FROM chat_sessions WHERE customer_id=$1", [customerId]);
}

/** Transcripts are kept for quality assurance and dispute handling, then purged nightly. */
export function startRetentionJob(days: number) {
  const purge = () =>
    pool.query("DELETE FROM transcript_messages WHERE created_at < now() - ($1 || ' days')::interval", [days]);
  setInterval(purge, 24 * 3600 * 1000);
}

import pino from "pino";

const logger = pino({ level: "info", base: { service: "supportbot" } });

export type LlmCall = {
  sessionId: string; model: string; promptTokens: number; completionTokens: number; latencyMs: number; handover: boolean;
};

/** One structured line per LLM call, shipped to Loki (retention set in config/app.yaml). */
export function logLlmCall(call: LlmCall) {
  logger.info({ event: "llm_call", ...call, model_version: call.model }, "llm reply generated");
}

import type { NextFunction, Request, Response } from "express";
import jwt from "jsonwebtoken";

const SECRET = process.env.SESSION_SIGNING_KEY!;

/** Anonymous chat sessions get a signed session token from the shop; customerId is set when logged in. */
export function sessionAuth(req: Request, res: Response, next: NextFunction) {
  try {
    const claims = jwt.verify(req.header("x-session-token") ?? "", SECRET) as { sid: string; cid?: string };
    res.locals.sessionId = claims.sid;
    res.locals.customerId = claims.cid ?? null;
    next();
  } catch {
    res.status(401).json({ error: "invalid session" });
  }
}

/** Staff SSO token with the `support-admin` role is required for transcript access and erasure. */
export function requireAdmin(req: Request, res: Response, next: NextFunction) {
  try {
    const claims = jwt.verify((req.header("authorization") ?? "").replace("Bearer ", ""), process.env.SSO_PUBLIC_KEY!, {
      algorithms: ["RS256"],
    }) as { roles?: string[] };
    if (!claims.roles?.includes("support-admin")) return res.status(403).end();
    next();
  } catch {
    res.status(401).end();
  }
}

